#!/usr/bin/env bash
# Every function's description and grants, in one place. Regenerates
# functions/<name>/<name>.json; never edit those by hand (bin/fnjson.py, as Tasks').
#   table   read        table:rw  + write rows        table:rwd  + delete rows
#   function:<name>     run it    workflow:<name>  start it    /folder:verbs   a folder
#   connector:<slug>    use the Lemma's connection
set -euo pipefail
cd "$(dirname "$0")/.."
f() { uv run --no-project python bin/fnjson.py "$@"; }
f release_notes_on_merge "A pull request closed on GitHub. When it merged into a watched repository: keeps it with its kind (Decisions: feature, improvement, fix, breaking, routine, internal) and the issues it closes, writes an ask for each issue author and 'me too' commenter, and hangs it on the open note. Answers skip otherwise." release_note_settings release_note:rw release_note_pr:rw ask:rw connector:github
f release_notes_draft "Redraft the open note around the writer agent. mode brief: the pull requests since the last release, routine and internal work folded out, grouped by issue, the leads chosen (Decisions), edited lines kept. mode save: writes the writer's lines, counts who asked, keeps every line a person edited." release_note:rw release_note_line:rwd release_note_pr:rw release_note_settings ask brand connector:github
f release_notes_on_live "A deploy signal (the deploy workflow's successful run, or a tag): marks the note's pull requests live whose merge commit the deployed commit contains, and the note ready. Never publishes." release_note_settings release_note:rw release_note_pr:rw connector:github
f release_notes_publish "Publish a note as the person who presses Publish: the GitHub release, the public changelog row, the Slack post; then the linked asks move to shipped and public askers get a reply proposed. Only publishers." release_note:rw release_note_line release_note_pr release_note_settings release_note_page:rw release_note_reply:rw ask:rw brand connector:github connector:slack
f release_notes_tell "Each member's own run on an ask they heard that shipped. mode brief: their thread and what shipped. mode save: the reply as a Mail draft in that thread, and 'Tell Jo it shipped' in their Today. Never sends." ask release_note release_note_line conversation message draft:rw mail_settings needs_you:rw
f release_notes_on_sent "Each member's own run on their drafts: a Release notes reply sent through Mail makes the ask told; thrown away, the item leaves Today." draft ask:rw needs_you:rw
f release_notes_on_note "Each member's own run when a note changes state, and on opening the app (refresh): a publisher's 'v2.14 notes are ready' in Today; after publishing, links suggested from their own conversations." release_note_settings release_note release_note_line needs_you:rw function:release_notes_suggest
f release_notes_suggest "After a note is published, as each member: their own conversations from the last 120 days whose ask matches a shipped line (one Decisions call each, at most 20) become suggested asks, for them to confirm in Who asked." release_note release_note_line conversation ask:rw
f release_notes_send_reply "Send one approved reply to a public asker as the person pressing Send: a comment on their GitHub issue, or a reply in their Slack thread; the ask is then told. A sample mail reply is only marked sent." release_note_reply:rw ask:rw draft:rw connector:github connector:slack
f release_notes_reconcile "Nightly: pull requests merged since the last release that the webhook missed go through release_notes_on_merge, the deploy workflow's newest successful run through release_notes_on_live, and the note is redrafted when anything new came in." release_note_settings release_note release_note_pr function:release_notes_on_merge function:release_notes_on_live workflow:release-notes-redraft connector:github
f release_notes_setup_save "Release notes' set-up: the product's name, repositories (each with how it goes live: the deploy workflow's name or a tag), the Slack channel, who publishes. Writes the memory block. Safe to run again." release_note_settings:rw function:release_notes_memory
f release_notes_setup_options "What set-up can offer: the repositories the shared GitHub connection can see, one repository's workflows, and the Slack channels; says plainly when a connection is missing." connector:github connector:slack
f release_notes_memory "Tells this Lemma's agents that Release notes is installed: its block in /memory/AGENTS.md and its guide at /memory/plugins/release-notes.md, leaving the team's notes alone. Set-up runs it; safe to run again. remove takes both out." /memory:read,write
f release_notes_sample_data "load: a made-up product's v2.14 (Fernway, .example people) to look around with, ready to publish. clear: removes only what the sample made and starts set-up again." release_note_settings:rwd release_note:rwd release_note_pr:rwd release_note_line:rwd release_note_page:rwd release_note_reply:rwd ask:rwd conversation:rwd message:rwd draft:rwd needs_you:rw release_note_sample_row:rwd function:release_notes_on_note
